import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { socket } from './socket';
import './DMPage.css';

const DMPage = ({ currentUser }) => {
  const navigate = useNavigate();
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [dmList, setDmList] = useState([]);
  const [selectedChat, setSelectedChat] = useState(null);
  const [conversations, setConversations] = useState([]);
  const [applications, setApplications] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);
  const messagesEndRef = useRef(null);

  const defaultAvatar = '/default-avatar.png';

  const getUserImage = (user) => user?.image || defaultAvatar;
  const getUserName = (user) => user?.name || 'Unknown User';
  const getUserRole = (user) => user?.role || 'user';

  const handleImageError = (e) => {
    e.target.onerror = null;
    e.target.src = defaultAvatar;
  };

  // Function to send messages
  const handleSend = async () => {
    if (!newMessage.trim() || !selectedChat) return;

    const messageData = {
      sender: currentUser._id,
      receiver: selectedChat._id,
      message: newMessage.trim(),
      timestamp: new Date().toISOString(),
    };

    setMessages((prev) => [...prev, messageData]);
    setNewMessage('');

    socket.emit('sendMessage', messageData);
  };

  // Function to accept application
  const handleAccept = () => {
    if (!selectedChat) return;

    socket.emit('acceptApplication', {
      clientId: currentUser._id,
      freelancerId: selectedChat._id,
    });
  };

  // Function to render application message
  const renderApplicationMessage = () => {
    return applications.some((app) => app.applicantId === selectedChat?._id) ? (
      <div className="system-message">This user has applied for a job.</div>
    ) : null;
  };

  useEffect(() => {
    const token = localStorage.getItem('token');
    const userData = localStorage.getItem('user');

    if (!token || !userData) {
      navigate('/login');
    } else {
      // Initialize socket with token
      socket.auth = { token };
      socket.connect();
    }

    return () => {
      socket.disconnect();
    };
  }, [navigate]);

  useEffect(() => {
    if (!currentUser?._id) return;

    const fetchUserDetails = async (userId) => {
      try {
        const response = await axios.get(`/api/users/${userId}`);
        return response.data;
      } catch {
        return { _id: userId, name: 'Unknown User', image: defaultAvatar, role: 'user' };
      }
    };

    const loadInitialData = async () => {
      try {
        const convResponse = await axios.get(`/api/conversations?userId=${currentUser._id}`);
        const convos = convResponse.data;
        setConversations(convos);

        const participants = Array.from(new Set(convos.flatMap((conv) =>
          conv.participants.filter((id) => id !== currentUser._id)
        )));

        const users = await Promise.all(participants.map((id) => fetchUserDetails(id)));
        setDmList(users);
      } catch {
        setError('Failed to load conversations');
      } finally {
        setIsLoading(false);
      }
    };

    loadInitialData();

    return () => {
      socket.off('receiveMessage');
      socket.off('newConversation');
      socket.off('newApplication');
    };
  }, [currentUser]);

  useEffect(() => {
    if (!currentUser?._id) return;

    const handleReceiveMessage = (message) => {
      setMessages((prev) => [...prev, message]);
    };

    const handleNewConversation = async (conversation) => {
      const otherParticipantId = conversation.participants.find((id) => id !== currentUser._id);

      if (otherParticipantId && !dmList.some((u) => u._id === otherParticipantId)) {
        const user = await fetchUserDetails(otherParticipantId);
        setDmList((prev) => [...prev, user]);
      }

      if (!conversations.some((c) => c._id === conversation._id)) {
        setConversations((prev) => [...prev, conversation]);
      }
    };

    const handleNewApplication = (appData) => {
      setApplications((prev) => [...prev, appData]);
      if (currentUser.role === 'client') {
        socket.emit('createConversation', {
          senderId: currentUser._id,
          receiverId: appData.applicantId,
        });
      }
    };

    socket.on('receiveMessage', handleReceiveMessage);
    socket.on('newConversation', handleNewConversation);
    socket.on('newApplication', handleNewApplication);

    return () => {
      socket.off('receiveMessage', handleReceiveMessage);
      socket.off('newConversation', handleNewConversation);
      socket.off('newApplication', handleNewApplication);
    };
  }, [currentUser, dmList, conversations]);

  return (
    <div className="dm-container">
      <div className="header">
        <img src="images/image10.png" alt="User" />
        <div className="header-right">
          <span onClick={() => navigate("/profile")}>Profile</span>
          <span onClick={() => navigate("/chat")}>Chat</span>
          <span onClick={() => navigate("/ong-proj")}>Ongoing Projects</span>
          <span onClick={() => navigate("/post")}>Post a Job</span>
          <span onClick={() => navigate("/contact")}>Contact Us</span>
          <span onClick={() => navigate("/abt")}>About</span>
        </div>
      </div>

      <div className="dm-main">
        <div className="dm-sidebar">
          <h2>Messages</h2>
          {dmList.length === 0 ? (
            <div className="empty-list">No conversations yet</div>
          ) : (
            dmList.map((user) => (
              <div key={user._id}
                className={`dm-user ${selectedChat?._id === user._id ? 'active' : ''}`}
                onClick={() => setSelectedChat(user)}
              >
                <img src={getUserImage(user)} alt={getUserName(user)}
                  className="user-avatar" onError={handleImageError} />
                <div className="user-info">
                  <h3>{getUserName(user)}</h3>
                  <p>{getUserRole(user)}</p>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="chat-area">
          {selectedChat ? (
            <>
              <div className="chat-header">
                <div className="chat-user">
                  <img src={getUserImage(selectedChat)} alt={getUserName(selectedChat)}
                    onError={handleImageError} />
                  <h3>{getUserName(selectedChat)}</h3>
                </div>
                {currentUser.role === 'client' && (
                  <button onClick={handleAccept} className="accept-btn"
                    disabled={!applications.some(app => app.applicantId === selectedChat._id)}>
                    Accept Client
                  </button>
                )}
              </div>

              <div className="messages-container">
                {renderApplicationMessage()}
                {messages.map((msg) => (
                  <div key={msg._id || msg.timestamp}
                    className={`message ${msg.sender === currentUser._id ? 'sent' : 'received'}`}>
                    <p>{msg.message}</p>
                  </div>
                ))}
                <div ref={messagesEndRef} />
              </div>

              <div className="message-input">
                <input type="text" value={newMessage} onChange={(e) => setNewMessage(e.target.value)}
                  placeholder="Type a message..." />
                <button onClick={handleSend} disabled={!newMessage.trim()}>Send</button>
              </div>
            </>
          ) : <div className="empty-chat">Select a conversation</div>}
        </div>
      </div>
    </div>
  );
};

export default DMPage;
